WITH cleaned AS (SELECT id, product_id, quantity, last_restock, ROUND(quantity * 1.07, 2) quantity_scaled FROM inventory WHERE last_restock >= DATE '2024-03-18') SELECT CASE WHEN quantity >= 234 THEN 'HIGH' ELSE 'LOW' END AS quantity_tier, DATE_TRUNC('YEAR', last_restock) AS year_start, COUNT(DISTINCT product_id) AS distinct_product_ids, COUNT(DISTINCT id) AS distinct_ids, PERCENTILE_APPROX(quantity_scaled, 0.9) AS quantity_scaled_p90 FROM cleaned GROUP BY quantity_tier, year_start HAVING COUNT(DISTINCT id) < 1;
